const BLACK = "#050505";
const BONE = "#F8F0E0";
const RED = "#E8203A";
const YELLOW = "#F8E028";
const GOLD = "#B8893F";
const MUTED = "#8C8780";
const BAR_COLORS = [YELLOW, RED, BONE, GOLD, YELLOW, RED];

function glyphs(table, text, size, x, y, spacing = 0, anchor = "start") {
  const scale = size / 1000;
  const items = [...String(text)].map((char) => table[char] || table["?"]);
  const total = items.reduce((sum, glyph) => sum + glyph.w * scale + spacing, -spacing);
  let cursor = anchor === "end" ? x - total : anchor === "middle" ? x - total / 2 : x;
  return items
    .map((glyph) => {
      const piece = glyph.d ? `<path transform="translate(${cursor.toFixed(1)} ${y}) scale(${scale})" d="${glyph.d}"/>` : "";
      cursor += glyph.w * scale + spacing;
      return piece;
    })
    .join("");
}

const mono = (text, size, x, y, spacing, anchor) => glyphs(GLYPHS.mono, text, size, x, y, spacing, anchor);
const bold = (text, size, x, y, spacing, anchor) => glyphs(GLYPHS.bold, text, size, x, y, spacing, anchor);

function frame(width, height, title, caption, body) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="${title}">
  <title>${title}</title>
  <rect width="${width}" height="${height}" fill="${BLACK}"/>
  <path d="M8 30 V8 H30 M${width - 30} 8 H${width - 8} V30 M8 ${height - 30} V${height - 8} H30 M${width - 30} ${height - 8} H${width - 8} V${height - 30}" fill="none" stroke="${BONE}" stroke-width="1.3"/>
  <path d="M8 8 h13 l-13 13 Z M${width - 8} 8 h-13 l13 13 Z M8 ${height - 8} h13 l-13 -13 Z M${width - 8} ${height - 8} h-13 l13 -13 Z" fill="${RED}"/>
  <g fill="${YELLOW}">${bold(title.toUpperCase(), 13, 34, 38, 4)}</g>
  <path d="M34 48 H${width - 34}" stroke="${RED}" stroke-width="1.2"/>
  ${body}
  <g fill="${MUTED}">${mono(caption, 8, width - 30, height - 14, 2, "end")}</g>
</svg>
`;
}

const number = (value) => (value === null || value === undefined ? "--" : Number(value).toLocaleString("en-US"));

export function renderStats(stats, caption) {
  const tiles = [
    ["Stars earned", stats.stars], ["Commits", stats.commits],
    ["Pull requests", stats.pullRequests], ["Issues", stats.issues],
    ["Followers", stats.followers], ["Public repos", stats.repos],
  ];
  const body = tiles.map(([label, value], index) => {
    const column = index % 2;
    const row = Math.floor(index / 2);
    const x = 34 + column * 228;
    const y = 66 + row * 42;
    return `<g fill="${BONE}">${bold(number(value), 24, x, y + 22, 0)}</g><g fill="${MUTED}">${mono(label, 10.5, x, y + 37, 0.6)}</g>`;
  }).join("");
  return frame(495, 214, "S4NTRX / Stats", caption, body);
}

export function renderLanguages(languages, caption) {
  const top = languages.slice(0, 6);
  const total = top.reduce((sum, item) => sum + item.bytes, 0) || 1;
  const rows = top.map((item, index) => {
    const y = 68 + index * 20;
    const percent = (item.bytes / total) * 100;
    const barWidth = Math.max(3, (percent / 100) * 250 * (total / (top[0].bytes || 1)) * (top[0].bytes / total));
    const name = item.name.length > 14 ? item.name.slice(0, 13) + "." : item.name;
    return `<g fill="${BONE}">${mono(name, 11.5, 34, y + 9, 0.4)}</g>
  <rect x="150" y="${y}" width="${(percent / 100) * 270 + 3}" height="9" fill="${BAR_COLORS[index]}"/>
  <g fill="${BONE}">${bold(percent.toFixed(1) + "%", 11, 461, y + 9, 0, "end")}</g>`;
  });
  const body = rows.length ? rows.join("\n  ") : `<g fill="${MUTED}">${mono("NO DATA YET", 12, 34, 100, 2)}</g>`;
  return frame(495, 214, "S4NTRX / Top languages", caption, body);
}

async function api(path, token) {
  const response = await fetch(`https://api.github.com${path}`, {
    headers: {
      Accept: "application/vnd.github+json",
      "User-Agent": "profile-cards-action",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
  });
  if (!response.ok) throw new Error(`GitHub API ${response.status} for ${path}`);
  return response.json();
}

export async function collect(user, token) {
  const profile = await api(`/users/${user}`, token);
  const repos = (await api(`/users/${user}/repos?per_page=100&type=owner`, token)).filter((repo) => !repo.fork);
  const totals = new Map();
  for (const repo of repos) {
    const bytes = await api(`/repos/${user}/${repo.name}/languages`, token);
    for (const [name, size] of Object.entries(bytes)) totals.set(name, (totals.get(name) || 0) + size);
  }
  const search = async (query) => (await api(`/search/${query.kind}?q=${encodeURIComponent(query.q)}&per_page=1`, token)).total_count;
  return {
    stats: {
      stars: repos.reduce((sum, repo) => sum + repo.stargazers_count, 0),
      commits: await search({ kind: "commits", q: `author:${user}` }),
      pullRequests: await search({ kind: "issues", q: `author:${user} type:pr` }),
      issues: await search({ kind: "issues", q: `author:${user} type:issue` }),
      followers: profile.followers,
      repos: profile.public_repos,
    },
    languages: [...totals.entries()].map(([name, bytes]) => ({ name, bytes })).sort((a, b) => b.bytes - a.bytes),
  };
}

async function write(path, svg) {
  let previous = "";
  try { previous = await readFile(path, "utf8"); } catch (error) { /* first run */ }
  if (previous !== svg) await writeFile(path, svg);
}

async function main() {
  const user = process.env.GH_USER || "s4ntrx";
  const data = process.env.CARDS_DATA ? JSON.parse(await readFile(process.env.CARDS_DATA, "utf8")) : await collect(user, process.env.GITHUB_TOKEN);
  const caption = process.env.CAPTION || `SYNCED ${new Date().toISOString().slice(0, 10)}`;
  await write(process.env.STATS_OUT || "assets/stats-card.svg", renderStats(data.stats, caption));
  await write(process.env.LANGS_OUT || "assets/languages-card.svg", renderLanguages(data.languages, caption));
  console.log("cards written");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((error) => { console.error(error.message); process.exit(1); });
}
